-- پایگاه داده تقسیمات کشوری ایران (SQL Server)
-- استان‌ها: 31 | شهرها: 1455 | روستاها: 95719 (منبع: iran-states-cities-districts)
IF DB_ID(N'IranGeo') IS NULL
    CREATE DATABASE IranGeo COLLATE Persian_100_CI_AI;
GO
USE IranGeo;
GO

IF OBJECT_ID('village') IS NOT NULL DROP TABLE village;
IF OBJECT_ID('city') IS NOT NULL DROP TABLE city;
IF OBJECT_ID('province') IS NOT NULL DROP TABLE province;
GO

CREATE TABLE province (
    pid  INT PRIMARY KEY,
    name NVARCHAR(100) NOT NULL
);

CREATE TABLE city (
    cid  INT PRIMARY KEY,
    pid  INT NOT NULL,
    name NVARCHAR(100) NOT NULL,
    CONSTRAINT FK_city_province FOREIGN KEY (pid) REFERENCES province(pid)
);

CREATE TABLE village (
    vid  INT PRIMARY KEY,
    cid  INT NOT NULL,
    name NVARCHAR(100) NOT NULL,
    CONSTRAINT FK_village_city FOREIGN KEY (cid) REFERENCES city(cid)
);
GO

